import{ENEMY_ROLES}from './enemy-behaviors.js';
import{CHASSIS,chassisBlueprint}from './chassis.js';
import{MISSIONS,missionTuning,campaignRound}from './mission-catalog.js';
import{LANDINGS,profileFor}from './campaign.js';
import{CONTRACTS,FIELD_MODULES}from './sortie-progression.js';
import{FIELD_UPGRADES,FIELD_ITEMS}from './field-catalog.js';
import{debriefMarkup,formatTime}from './sortie-view.js';
import{cleanBuild,EQUIPMENT,ABILITIES,mechStats,buildKey,validBuild}from './core.js?v=41';
import{itemIcon}from './workshop-icons.js?v=41';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=id=>EQUIPMENT[id].name.split(' / ').at(-1);
const runBuildMarkup=profile=>[[profile.upgrades,FIELD_UPGRADES],[profile.items,FIELD_ITEMS],[profile.modules,FIELD_MODULES]].map(([ids,catalog])=>[...new Set(ids||[])].map(id=>`<div><strong>${escape(catalog[id].name)}</strong><span>${escape(catalog[id].detail)}</span><b>×${ids.filter(value=>value===id).length}</b></div>`).join('')).join('')||'<p>No carried field hardware yet.</p>';
const TABS=[['operations','Operations'],['loadout','Loadout'],['refits','Refits'],['contracts','Contracts'],['report','Report']];
export const CAMPAIGN_MECHS=Object.values(CHASSIS).map(c=>({label:c.name,role:`${c.size} / ${c.role}`,build:cleanBuild(chassisBlueprint(c.id))}));

// A field survey plate: all cover, platforms and objective sites come from the playable mission.
function battlefield(spec){
 const round=campaignRound(spec.id),project=(x,y)=>[150+x*.245,62+y*.245],point=(x,y)=>project(x,y).map(v=>v.toFixed(1)).join(','),entry=project(round.entry.x,round.entry.y),index=MISSIONS.indexOf(spec);
 const contour=(cx,cy,r,i)=>{const points=Array.from({length:33},(_,j)=>{const a=j/32*Math.PI*2,rr=r*(1+.11*Math.sin(a*3+index)+.055*Math.cos(a*7));return`${cx+Math.cos(a)*rr},${cy+Math.sin(a)*rr*.71}`;});return`<path d="M${points.join('L')}Z"/>`;};
 const block=o=>{const[x,y]=project(o.x,o.y),w=o.w*.245,h=o.h*.245;return`<g><rect x="${x+3}" y="${y+4}" width="${w}" height="${h}" fill="#080a08"/><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${o.landmark?'#8d8a73':'#676854'}" stroke="#d0c9a7" stroke-width="1.2"/>${o.cargo?`<path d="M${x+w*.28} ${y}v${h}m${w*.42} ${-h}v${h}" stroke="#272a22" stroke-width="2"/>`:''}</g>`;};
 const objectives=round.points.map((p,i)=>{const[x,y]=project(p.x,p.y);return`<g class="survey-objective"><path d="M${x-30} ${y}h60M${x} ${y-30}v60" stroke="#e6d9bd" opacity=".45"/><circle cx="${x}" cy="${y}" r="22" fill="#bb3d2b" stroke="#f2d6bd" stroke-width="1.5"/><circle cx="${x+1}" cy="${y-1}" r="30" fill="none" stroke="#cf4e37" stroke-width="1.5" stroke-dasharray="85 35 30 60" transform="rotate(${i*36} ${x} ${y})"/><text x="${x}" y="${y+6}" text-anchor="middle" fill="#fff0d5" font-size="18" font-weight="700">${String(i+1).padStart(2,'0')}</text><text x="${x+37}" y="${y-12}" fill="#d4c5a6" font-size="10" letter-spacing="1"></text></g>`;}).join('');
 return`<svg class="battlefield-scan" viewBox="0 0 940 690" role="img" aria-label="Field survey of ${escape(spec.name)}. ${round.points.length} objective sites, actual cover and insertion zone."><defs><pattern id="survey-grid" width="64" height="64" patternUnits="userSpaceOnUse"><path d="M64 0H0V64" fill="none" stroke="#b8b59b" stroke-opacity=".15" stroke-width="1"/></pattern><pattern id="survey-hatch" width="9" height="9" patternUnits="userSpaceOnUse" patternTransform="rotate(40)"><path d="M0 0V9" stroke="#a49f80" stroke-opacity=".2" stroke-width="2"/></pattern><clipPath id="survey-clip"><rect x="150" y="62" width="637" height="563.5"/></clipPath></defs><g fill="none" stroke="#96977b" stroke-width="1" opacity=".18">${[80,115,150,185,220,255,290,325,360,395].map((r,i)=>contour(260,190,r,i)).join('')}${[60,95,130,165,200,235,270].map((r,i)=>contour(780,570,r,i)).join('')}</g><g clip-path="url(#survey-clip)"><rect x="150" y="62" width="637" height="563.5" fill="#383c30" fill-opacity=".75"/><rect x="150" y="62" width="637" height="563.5" fill="url(#survey-grid)"/><g stroke="#8a8d70" stroke-width="14" opacity=".15"><path d="M${point(230,450)}L${point(2380,450)}M${point(230,1850)}L${point(2380,1850)}M${point(1300,200)}L${point(1300,2080)}"/></g>${spec.theme==='spillway'?`<path d="M${point(0,1100)}L${point(2600,1100)}" stroke="#949d89" opacity=".35" stroke-width="24"/>`:spec.theme==='rail'?`<path d="M${point(0,200)}L${point(2600,2100)}M${point(2500,0)}L${point(200,2300)}" stroke="#d4c6a5" opacity=".4" stroke-width="4"/>`:''}${round.platforms.map(p=>{const[x,y]=project(p.x,p.y);return`<rect x="${x}" y="${y}" width="${p.w*.245}" height="${p.h*.245}" fill="url(#survey-hatch)" stroke="#aaa18b"/>`;}).join('')}${round.obstacles.filter(o=>o.cargo||o.landmark).map(block).join('')}<polyline points="${point(round.entry.x,round.entry.y)} ${round.points.map(p=>point(p.x,p.y)).join(' ')}" fill="none" stroke="#d76a4c" stroke-opacity=".75" stroke-width="2" stroke-dasharray="9 8"/>${objectives}<g><path d="M${entry[0]} ${entry[1]-13}l12 23h-24Z" fill="#e4d2af"/><text x="${entry[0]+22}" y="${entry[1]+7}" fill="#e1d2b2" font-size="12" letter-spacing="2">Drop zone</text></g></g><rect x="150" y="62" width="637" height="563.5" fill="none" stroke="#b9b296" stroke-opacity=".45"/>${Array.from({length:8},(_,i)=>`<text x="${150+i*91}" y="46" text-anchor="middle" fill="#a3a18a" font-size="11">${String(42+i).padStart(2,'0')}</text><path d="M${150+i*91} 53v9M${150+i*91} 626v9" stroke="#a3a18a" opacity=".5"/>`).join('')}${Array.from({length:7},(_,i)=>`<text x="130" y="${68+i*93}" text-anchor="end" fill="#a3a18a" font-size="11">${String(16+i).padStart(2,'0')}</text><path d="M141 ${62+i*93}h9M787 ${62+i*93}h9" stroke="#a3a18a" opacity=".5"/>`).join('')}<g transform="translate(844 100)" fill="none" stroke="#bdb69d" stroke-width="1.5"><path d="M0 45V0m-9 15L0 0l9 15"/><text x="0" y="-12" text-anchor="middle" fill="#bdb69d" stroke="none" font-size="13">N</text></g><path d="M654 658h132m-132-5v10m66-10v10m66-10v10" stroke="#a7a28c"/><text x="654" y="680" fill="#a7a28c" font-size="10" letter-spacing="1">0</text><text x="786" y="680" text-anchor="end" fill="#a7a28c" font-size="10" letter-spacing="1">500 m</text></svg>`;
}

const serviceSymbol=role=>`<svg class="service-symbol" viewBox="0 0 64 64" aria-hidden="true">${({ASSAULT:'<path d="M13 48 42 19m-8-7 18 18M8 39l17 17M29 19 12 36l16 16 17-17"/>',BREACH:'<path d="M16 10h32v44H16zM10 23h44M10 41h44M26 10v44m12-44v44"/>',SURVIVAL:'<path d="M32 7 52 16v16C52 45 32 57 32 57S12 45 12 32V16Zm0 10v29M22 32h20"/>',RECOVERY:'<path d="M24 10h16v14h14v16H40v14H24V40H10V24h14Z"/>',MOBILITY:'<path d="m10 36 22-25 22 25M10 52l22-25 22 25"/>',SYSTEMS:'<path d="M10 20h16v-8h12v40H26v-8H10Zm28 0h16v24H38M16 26v12m32-12v12"/>'})[role]||'<path d="M32 8 54 50H10Z"/>'}</svg>`;

export function createCampaignView(root,actions){
 let inspected=0,latest,pending=null,tab='operations';
 root.addEventListener('click',event=>{
  const target=event.target.closest('[data-tab],[data-action],[data-level],[data-contract],[data-refit]');if(!target||target.disabled)return;
  if(target.dataset.tab){tab=target.dataset.tab;render(latest);root.querySelector(`[role="tab"][data-tab="${tab}"]`)?.focus({preventScroll:true});return;}
  if(target.dataset.level!==undefined){inspected=Number(target.dataset.level);render(latest);root.closest('.menu-stage')?.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
  if(target.dataset.contract){actions.contract(target.dataset.contract);return;}
  if(target.dataset.refit){pending={revision:latest.campaign.revision,id:target.dataset.refit};actions.refit(pending);render(latest);return;}
  if(target.dataset.action==='focus'){inspected=Math.min(8,latest.campaign.level);tab='operations';render(latest);return;}
  if(target.dataset.action==='drill'){actions.drill(MISSIONS[inspected].id);return;}
  actions[target.dataset.action]?.();
 });
 root.addEventListener('keydown',event=>{
  const target=event.target.closest('[role="tab"]');if(!target||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
  event.preventDefault();const i=TABS.findIndex(([id])=>id===tab);tab=TABS[event.key==='Home'?0:event.key==='End'?TABS.length-1:(i+(event.key==='ArrowRight'?1:-1)+TABS.length)%TABS.length][0];render(latest);const selected=root.querySelector(`[role="tab"][data-tab="${tab}"]`);selected?.focus();selected?.scrollIntoView({block:'nearest',inline:'nearest'});
 });
 root.addEventListener('change',event=>{if(event.target.id==='campaignMech')actions.mech(event.target.value);if(event.target.id==='campaignSpecial')actions.special(event.target.value);if(event.target.id==='campaignLanding')actions.landing(event.target.value);});
 function render(state){
  if(!state?.campaign){root.innerHTML='';latest=state;return;}
  if(state.campaign.id!==latest?.campaign?.id||state.campaign.level!==latest?.campaign?.level){inspected=Math.min(8,state.campaign.level);tab='operations';}
  latest=state;const {campaign,build,saved,members,localId,room,isHost,connecting,canChoose,licensed=true,deploymentStats}=state;
  if(pending&&pending.revision!==campaign.revision)pending=null;
  const focused=root.contains(document.activeElement)?document.activeElement:null,focusId=focused?.id;
  const focusData=focused&&['tab','action','level','contract','refit'].map(k=>focused.dataset[k]!==undefined?[k,focused.dataset[k]]:null).find(Boolean);
  const spec=MISSIONS[inspected],current=MISSIONS[Math.min(8,campaign.level)],active=campaign.runState==='active',self=members.find(p=>p.id===localId)||members[0],profile=profileFor(campaign,self.name),stats=deploymentStats||mechStats(build),valid=validBuild(build)&&licensed,allReady=members.every(p=>p.ready&&validBuild(p.build)),contract=CONTRACTS.find(c=>c.id===campaign.contract),landing=LANDINGS.find(l=>l.id===campaign.landing);
  const options=[...CAMPAIGN_MECHS.map((p,i)=>({value:'preset-'+i,label:p.label+' · '+p.role,build:p.build})),...saved.map((b,i)=>({value:'saved-'+i,label:'Saved · '+b.name,build:b}))],match=options.find(p=>buildKey({...p.build,equipment:[...p.build.equipment.slice(0,2),build.equipment[2]]})===buildKey(build)),tuning=missionTuning(inspected,members.length),record=campaign.records[spec.id+':'+campaign.contract];
  const heading=(title,copy)=>`<header class="command-panel-heading"><h2>${title}</h2><p>${copy}</p></header>`;
  const operations=`<section class="operation-theatre"><div class="operation-map">${battlefield(spec)}</div><div class="operation-order"><div class="operation-heading"><span class="order-number">${String(inspected+1).padStart(2,'0')}</span><div><p class="mission-context">Act ${spec.act} · ${spec.kind}</p><span class="operation-state ${inspected<campaign.level?'secured':''}">${inspected<campaign.level?'Secured':active&&inspected===campaign.level?'Next mission':'Practice available'}</span></div></div><h2>${escape(spec.name)}</h2><p class="operation-summary">${escape(spec.brief)}</p><dl class="order-facts"><div><dt>Duration</dt><dd>${spec.minutes}<small> min</small></dd></div><div><dt>Salvage</dt><dd>${spec.reward}<small> cr</small></dd></div></dl></div></section><nav class="operation-route" aria-label="Campaign mission route">${MISSIONS.map((m,i)=>`<button data-level="${i}" class="route-stop ${i<campaign.level?'complete':''} ${i===campaign.level&&active?'current':''}" aria-pressed="${inspected===i}" ${i===campaign.level&&active?'aria-current="step"':''} aria-label="Mission ${i+1}: ${escape(m.name)}${i<campaign.level?', secured':i===campaign.level&&active?', next drop':''}" title="${escape(m.name)}"><span>${i<campaign.level?'✓':String(i+1).padStart(2,'0')}</span></button>`).join('')}</nav><div class="operation-intel"><span>Opposition: ${[...new Set(spec.mix)].map(t=>({drone:'Swarm',gunner:'Aerial',tank:'Armor'}[t]||ENEMY_ROLES[t]?.name||t)).join(' / ')}</span><button class="command-link" data-action="drill" ${connecting||room&&!isHost?'disabled':''}>Practice this mission <span>↗</span></button></div><details class="operation-advice"><summary>Pilot’s advice</summary><p>${escape(spec.lesson)}</p></details>${inspected!==Math.min(8,campaign.level)?'<button class="command-return" data-action="focus">← Return to your next drop</button>':''}`;
  const loadout=`${heading('Loadout','Choose a mech, special ability and insertion point.')}<div class="command-loadout"><div class="fitting-card"><label class="campaign-field" for="campaignMech">Your machine<select id="campaignMech"><option value="current" ${!match?'selected':''}>Current / ${escape(build.name)}</option>${options.map(p=>`<option value="${p.value}" ${match?.value===p.value?'selected':''}>${escape(p.label)}</option>`).join('')}</select></label><div class="command-machine"><svg viewBox="0 0 180 160" aria-hidden="true"><path d="M70 15h40l10 18-8 44H68l-8-44Zm-8 17-22 9-9 53 22 8 17-44m48-26 22 9 9 53-22 8-17-44M69 80l-7 34-6 32h26l8-50 8 50h26l-6-32-7-34M75 24h30v15H75Z" fill="none" stroke="currentColor" stroke-width="4"/><path d="M75 45h30v26H75Zm-33 9-5 32m101-32 5 32M64 123h18m17 0h18" fill="none" stroke="currentColor" stroke-width="2"/></svg><div data-deployment-stats><strong>${stats.weight}<small> / ${stats.capacity}t</small></strong><span>${stats.hp} armor</span><b class="${valid?'online':'offline'}">${valid?'Systems ready':licensed?'Refit required':'License required'}</b></div></div><button class="command-button" data-action="workshop">Open workshop <span>↗</span></button></div><div class="fitting-card equipment-fit"><div class="command-weapons">${build.equipment.slice(0,2).map((id,i)=>`<div>${itemIcon('equip'+i,id,EQUIPMENT[id])}<div><small>${i?'Right':'Left'} hand</small><strong>${escape(short(id))}</strong></div></div>`).join('')}</div><label class="campaign-field" for="campaignSpecial">Special ability · E<select id="campaignSpecial">${Object.entries(ABILITIES).map(([id,item])=>`<option value="${id}" ${build.equipment[2]===id?'selected':''}>${escape(item.name)} · ${item.weight}t</option>`).join('')}</select></label><p class="fitting-description">${escape(ABILITIES[build.equipment[2]].desc)}</p></div><div class="fitting-card insertion-fit"><label class="campaign-field" for="campaignLanding">Approach<select id="campaignLanding" ${!canChoose?'disabled':''}>${LANDINGS.map(p=>`<option value="${p.id}" ${p.id===campaign.landing?'selected':''}>${p.name}</option>`).join('')}</select></label><p class="fitting-description">${escape(landing?.detail||'')}</p><span class="host-note">${canChoose?'You control the approach.':'The squad host selects insertion.'}</span></div></div>`;
  const refits=`${heading('Run supplies','Refit tokens are spent at the Run supplies station in Anchorage.')}<div class="refit-ledger"><strong>${profile.credits}<span>refit token${profile.credits===1?'':'s'} available</span></strong><span>${profile.modules.length} / 18 modules installed</span></div><button class="command-button" data-action="supply">Visit Run supplies <span>↗</span></button><div class="installed-modules"><h3>Carried field build</h3>${runBuildMarkup(profile)}</div>`;
  const contracts=`${heading('Contracts','Choose the opposition for your squad. Higher pressure earns more salvage.')}<div class="command-contracts">${CONTRACTS.map((c,i)=>`<button data-contract="${c.id}" aria-pressed="${campaign.contract===c.id}" ${!canChoose||!active?'disabled':''}><span class="contract-number">${serviceSymbol(['SURVIVAL','ASSAULT','BREACH'][i])}<i>${'▰'.repeat(i+1)}${'▱'.repeat(2-i)}</i></span><strong>${c.name}</strong><span>${c.id==='frontline'?'Balanced encounters. Room to regroup between reinforcement waves.':c.id==='overrun'?'Relentless reinforcements. Shorter breaks between every enemy wave.':'Armored opposition. More heavy enemies in every reinforcement wave.'}</span><b>${c.reward===1?'Standard salvage':'+'+Math.round((c.reward-1)*100)+'% salvage'}</b><em>${campaign.contract===c.id?'✓ Selected':'Select contract →'}</em></button>`).join('')}</div><p class="host-note">${canChoose?'Changing the contract clears squad readiness.':'The squad host chooses the contract.'}</p><div class="contract-intel"><h3>Current battlefield pressure</h3><dl><div><dt>Enemy armor</dt><dd>${tuning.health.toFixed(2)}×</dd></div><div><dt>Attack pressure</dt><dd>${tuning.damage.toFixed(2)}×</dd></div><div><dt>Best extraction</dt><dd>${record?formatTime(record):'—'}</dd></div></dl></div>`;
  const report=campaign.lastReport?debriefMarkup(campaign.lastReport,true):`${heading('Combat record','Mission results, salvage and squad performance are filed here after deployment.')}<div class="command-empty"><span class="empty-symbol">↗</span><h3>No sorties recorded.</h3><p>The front is waiting. Prepare your machine and make the first drop.</p><button class="command-button" data-tab="operations">Review the mission <span>→</span></button></div>`;
  root.innerHTML=`<header class="command-heading"><div><h1>The Cinder Front<span>${room?'Co-op':'Solo'}</span></h1></div><div class="command-progress"><span><b>${Math.min(9,campaign.level)}</b> / 9 secured</span><div aria-hidden="true">${MISSIONS.map((_,i)=>`<i class="${i<campaign.level?'done':i===campaign.level&&active?'next':''}"></i>`).join('')}</div></div></header><nav class="command-tabs" role="tablist" aria-label="Campaign command sections">${TABS.map(([id,label],i)=>`<button type="button" role="tab" id="command-tab-${id}" aria-controls="command-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-tab="${id}">${label}${id==='refits'&&profile.credits?`<b>${profile.credits}</b>`:id==='report'&&campaign.lastReport?'<i></i>':''}</button>`).join('')}</nav>${!active?`<div class="command-result" role="status"><strong>${campaign.runState==='won'?'Campaign complete':'Run ended'}</strong><span>${campaign.runState==='won'?'The Crown Engine has fallen. Your squad secured the front.':'Regroup, rebuild and return to the front.'}</span>${canChoose?'<button data-action="newRun">Start a new run ＋</button>':''}</div>`:campaign.lastResult==='victory'&&profile.credits?`<button class="earned-upgrade" data-tab="refits"><span>＋ ${profile.credits} upgrade choice${profile.credits===1?'':'s'} ready</span> Refit before your next drop <b>→</b></button>`:''}<div class="campaign-command-grid"><section id="command-panel" class="command-panel" role="tabpanel" aria-labelledby="command-tab-${tab}" tabindex="0">${({operations,loadout,refits,contracts,report})[tab]}</section><aside class="launch-dock" aria-label="Deployment controls"><div class="dock-setup"><button data-tab="loadout"><span>Machine<strong>${escape(build.name)}</strong></span><b>↗</b></button><div><span>Insertion<strong>${escape(landing?.name||'Central drop')}</strong></span><span>Contract<strong>${escape(contract?.name||'Frontline')}</strong></span></div></div><div class="dock-squad"><div class="dock-squad-title"><h3>Squad</h3><span>${members.length} / 4 pilots</span></div>${members.map((p,i)=>`<div class="dock-pilot ${p.ready||!room?'ready':''}"><span class="pilot-mark">${String(i+1).padStart(2,'0')}</span><div><strong>${escape(p.name)}${p.id===localId?'<small>You</small>':''}</strong><span>${room?p.ready?'Ready':'Preparing':'Ready'}</span></div><b>${p.ready||!room?'✓':'○'}</b></div>`).join('')}<div class="dock-connect">${room?`<span class="room-code">${escape(room)} / ${isHost?'Host':'Guest'}</span><button data-action="invite">Invite ＋</button><button data-action="leave" aria-label="Leave squad">Leave</button>`:`<button data-action="host" ${connecting?'disabled':''}>Invite friends <span>＋</span></button><button data-action="join" ${connecting?'disabled':''}>Join squad ↗</button>`}</div></div><div class="dock-launch">${!valid?`<p class="dock-error" role="status">${escape(licensed?stats.issues.join(' '):'License fitted gear at Anchorage vendors before deployment.')}<button data-action="workshop">Fix in workshop ↗</button></p>`:''}${room?`<button class="dock-ready" data-action="ready" ${connecting||!valid||!active?'disabled':''}>${self.ready?'✓ Ready / Undo':'Mark ready ✓'}</button>`:''}<button class="deploy-command" data-action="deploy" ${connecting||!active||!valid||room&&(!isHost||!allReady)?'disabled':''}><span>${active?room?(isHost?'Deploy squad':'Awaiting host'):'Deploy':'Run finished'}<small>${active?escape(current.name):'Return to the front with a new campaign'}</small></span><b>↗</b></button><p class="dock-status" role="status">${connecting?'Connecting to the squad…':room?`${members.filter(p=>p.ready).length}/${members.length} pilots ready. ${isHost?'Everyone must be ready to deploy.':'Your host launches the mission.'}`:''}</p></div></aside></div><footer class="command-footer"><button data-action="legacy">Classic operation ↗</button><span>Campaign advances in order. Practice missions award no upgrades.</span>${canChoose?'<button data-action="newRun">New run ＋</button>':''}</footer>`;
  for(const notice of root.querySelectorAll(':scope > .earned-upgrade,:scope > .command-result')){if(tab==='refits'&&notice.classList.contains('earned-upgrade'))notice.remove();else root.querySelector('#command-panel').prepend(notice);}
  if(focusData)root.querySelector('[data-'+focusData[0]+'="'+focusData[1]+'"]')?.focus({preventScroll:true});
  if(focusId)root.querySelector('#'+focusId)?.focus({preventScroll:true});
 }
 return{render,focusLanding(c){inspected=Math.min(8,c?.level||0);}};
}
